package com.miui.utils;import android.graphics.Bitmap;import android.graphics.drawable.*;public abstract class DrawableUtils {public static int calls,lastWidth,lastHeight;public static boolean returnNull;public static Bitmap drawable2Bitmap(Drawable d,int w,int h){calls++;lastWidth=w;lastHeight=h;d.setBounds(0,0,Math.max(w,d.getIntrinsicWidth()),Math.max(h,d.getIntrinsicHeight()));if(d.throwConversion)throw new IllegalStateException("convert");if(returnNull||d.getIntrinsicWidth()<=0||d.getIntrinsicHeight()<=0)return null;return d.bitmap;}}
